# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: gather
def gather(xs, limit=5):
    return [v if v <= limit else limit for v in xs]

# region: sift
def sift(xs):
    return [v for v in xs if v % 2 == 0]

# region: fold
def fold(xs, limit=5):
    return [v if v <= limit else limit for v in xs[1:]]

# region: emit
def emit(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: digest
def digest(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return digest(emit(fold(sift(gather(shape(raw))))))

